from pathlib import Path
import re
root=Path("/srv/atlas/static/assets")
js_path=root/"atlas-v10.js"
css_path=root/"atlas-v10.css"
js=js_path.read_text()
HOME='function home(){const curated=[\'fictiv\',\'formlabs\',\'gensler\',\'kuka\',\'protolabs\',\'xometry\',\'sandvik-coromant\',\'hexagon\',\'igus\',\'arburg\'].map(id=>state.sites.find(s=>s.id===id)).filter(Boolean);\n  const highlights=curated.slice(0,7);const focusModule=[\'fictiv-capability-hero\',\'gensler-project-gallery\',\'protolabs-service-grid\',\'xometry-rfq-first\'].map(id=>state.modules.find(x=>x.id===id)).filter(Boolean);\n  return `<div class="homepage">\n    <div class="wrap introduction"><div><p class="mini-label">B2B DESIGN REFERENCE LIBRARY</p><h1>Find better website references.</h1><p class="hero-note">Real B2B websites and page sections, selected for useful design decisions.</p></div><form id="search-home" class="intro-search"><label for="search-home-input" class="sr-only">Search the design collection</label>${svg(\'search\')}<input id="search-home-input" type="search" placeholder="Search websites, industries, or sections"><button type="submit" aria-label="Search references">${svg(\'right\')}</button></form></div>\n    <div class="wrap filters-quick"><span>Browse</span><div>${listIndustries().slice(0,7).map(x=>`<a href="/websites?sector=${encodeURIComponent(x)}" data-link="/websites?sector=${encodeURIComponent(x)}">${escapeHTML(x)}</a>`).join(\'\')}</div></div>\n    <section class="wrap home-gallery" aria-labelledby="home-gallery-title"><header class="shelf-heading"><div><div class="block-kicker">CURATED WEBSITES</div><h2 id="home-gallery-title">Selected references <span class="heading-count">${String(state.sites.length).padStart(2,\'0\')}</span></h2></div><a class="simple-link" href="/websites" data-link="/websites">View all ${svg(\'right\')}</a></header>\n      <div class="home-wall">${highlights.map((item,index)=>websiteCard(item,{index,featured:index===0})).join(\'\')}</div></section>\n    <section class="home-split-band"><div class="wrap split-band-inner"><div class="split-band-copy"><span class="subhead-white">SECTION STUDIES</span><h2>Look closer.</h2><p>Compare specific parts of real B2B pages — heroes, capabilities, products, process and RFQ.</p><a href="/sections" data-link="/sections">Browse sections ${svg(\'right\')}</a></div><div class="split-band-examples">${focusModule.slice(0,2).map((x,i)=>`<a href="${moduleHref(x.id)}" data-link="${moduleHref(x.id)}" class="dark-preview ${i?\'dark-preview-alt\':\'\'}">${capture(x)}<span>${escapeHTML(x.category)} <b>${escapeHTML(owner(x)?.name)}</b></span></a>`).join(\'\')}</div></div></section>\n    <section class="wrap more-sections"><header class="shelf-heading"><div><div class="block-kicker">REAL PAGE SECTIONS</div><h2>Details worth studying</h2></div><a class="simple-link" href="/sections" data-link="/sections">View all ${svg(\'right\')}</a></header><div class="home-module-grid">${focusModule.map((x,i)=>moduleCard(x,{index:i})).join(\'\')}</div></section>\n  </div>`;\n}\n'
LIB='function library(mode){const sites=mode===\'websites\';const filterButtons=sites?listIndustries().map(x=>`<button data-filter="sector" data-value="${escapeHTML(x)}" class="${state.sector===x?\'active\':\'\'}">${escapeHTML(x)}</button>`).join(\'\'):categories().map(x=>`<button data-filter="category" data-value="${escapeHTML(x)}" class="${state.category===x?\'active\':\'\'}">${escapeHTML(x)}</button>`).join(\'\');return `<div class="library-page"><div class="wrap library-masthead"><div><div class="overline">${sites?\'WEBSITE LIBRARY\':\'SECTION LIBRARY\'}</div><h1>${sites?\'Websites\':\'Sections\'}</h1></div><p>${sites?\'Real B2B websites, selected for useful visual and structural references.\':\'Real page sections, cropped from original websites and grouped by purpose.\'}</p></div>\n<div class="wrap library-main library-main--full">${toolbar(mode)}<div class="filter-strip"><button data-clear-filters class="${sites?!state.sector:!state.category?\'active\':\'\'}">All</button>${filterButtons}</div><div id="gallery-output"></div></div></div>`}\n'
js,n1=re.subn(r"function home\(\)\{.*?(?=function selectedItems)",HOME,js,flags=re.S)
js,n2=re.subn(r"function library\(mode\)\{.*?(?=function drawLibrary)",LIB,js,flags=re.S)
if n1!=1 or n2!=1:
    raise SystemExit(f"V1.2 JS patch mismatch: home={n1} library={n2}")
js_path.write_text(js)
css=css_path.read_text()
OVERRIDE='/* V1.2 — refined monochrome system: white canvas, restrained gray sections, no color accents */\n:root{\n  --paper:#FFFFFF;\n  --paper2:#F5F5F7;\n  --canvas:#FFFFFF;\n  --ink:#111111;\n  --ink2:#1D1D1F;\n  --muted:#6E6E73;\n  --subtle:#98989D;\n  --line:#E5E5E7;\n  --line2:#F0F0F2;\n  --accent:#111111;\n  --accent-soft:#F5F5F7;\n  --navy:#111111;\n  --sage:#F2F2F4;\n  --mint:#E7E7EA;\n}\nhtml,body{background:#fff;color:var(--ink)}\nbody{font-family:Inter,-apple-system,BlinkMacSystemFont,"SF Pro Text","Helvetica Neue",Arial,sans-serif;letter-spacing:-.01em}\n.wrap{width:min(calc(100% - 96px),1440px)}\n.site-header{position:sticky;top:0;background:rgba(255,255,255,.92);backdrop-filter:saturate(180%) blur(18px);border-bottom:1px solid rgba(17,17,17,.07)}\n.nav-inner{height:72px}.brand-symbol{background:#111;border-radius:12px;transform:none;box-shadow:none}.brand-symbol i,.brand-symbol i:nth-child(2),.brand-symbol i:nth-child(3){background:#fff}\n.brand-name{font-size:21px;color:#111}.brand-name span{color:#777;font-weight:500}\n.primary-nav a{color:#666}.primary-nav a.active:after{height:2px;background:#111}.nav-search,.tool-icon,.menu-toggle{border-color:#E5E5E7;background:#fff;box-shadow:none}.nav-search:hover,.tool-icon:hover,.menu-toggle:hover{background:#F5F5F7;border-color:#D8D8DC}.nav-board{background:#111;color:#fff;box-shadow:none}.tool-icon .tiny-count{background:#111}\n.front-ribbon{display:none}\n.overline,.block-kicker,.mini-label{color:#7C7C80}.simple-link{color:#111;border-color:#BEBEC2}.simple-link:hover{color:#000;border-color:#111}.heading-count{color:#A5A5AA}\n/* Home */\n.introduction{display:grid;grid-template-columns:minmax(0,1fr) minmax(360px,520px);gap:64px;align-items:end;padding:64px 0 36px;background:#fff}.introduction h1{font-size:clamp(42px,4.2vw,66px);line-height:1.02;letter-spacing:-3.2px;font-weight:760;margin:8px 0 14px;max-width:760px}.introduction h1 span{color:#111}.hero-note{font-size:15px;line-height:1.6;color:#666;max-width:560px;margin:0}.intro-search{height:58px;border:1px solid #DEDEE2;border-radius:16px;box-shadow:none;padding:7px 7px 7px 18px}.intro-search input{font-size:14px}.intro-search button{background:#111;border-radius:11px;width:44px;height:44px;box-shadow:none}.intro-search button:hover{background:#2A2A2A}.filters-quick{padding:14px 0 24px;margin-bottom:36px;border-top:0;border-bottom:1px solid var(--line)}.filters-quick>span{color:#8A8A8E}.filters-quick a{border:0;background:#F5F5F7;color:#3A3A3C;border-radius:999px;padding:9px 14px}.filters-quick a:hover{background:#EAEAED;color:#111}\n.home-gallery{padding-bottom:96px}.shelf-heading{margin-bottom:22px}.shelf-heading h2{font-size:28px;letter-spacing:-1.2px}.home-wall{grid-template-columns:repeat(3,minmax(0,1fr));gap:46px 20px}.home-wall>.site-tile--featured:first-child{grid-column:span 2}.home-wall>.site-tile:nth-child(5){grid-column:span 1}.home-wall .site-tile--featured .site-image{aspect-ratio:1.62}.site-image,.module-picture{background:#F5F5F7;border:1px solid #E8E8EA;border-radius:14px;box-shadow:none}.site-tile:hover .site-image,.module-tile:hover .module-picture{transform:none;box-shadow:0 16px 38px rgba(0,0,0,.08)}.site-tile:hover .site-image img{transform:scale(1.012)}.shot-actions button,.module-picture-actions .shot-save{border-color:#E4E4E7;background:rgba(255,255,255,.96);color:#111;box-shadow:0 2px 8px rgba(0,0,0,.06)}.shot-actions .saved,.module-picture-actions .saved{background:#111;color:#fff;border-color:#111}.tile-source{color:#111;background:#fff}.tile-source:hover{background:#111;color:#fff;border-color:#111}.tile-domain{color:#999}.site-tile-footer p{color:#777}.tile-name{font-weight:700;color:#111}\n.home-split-band{background:#F5F5F7;color:#111;padding:76px 0;border-top:1px solid #ECECEF;border-bottom:1px solid #ECECEF}.split-band-inner{grid-template-columns:.78fr 1.22fr;gap:72px}.subhead-white{color:#888}.split-band-copy h2{font-size:clamp(36px,3.5vw,54px);letter-spacing:-2px;margin:12px 0 16px}.split-band-copy p{color:#666;max-width:390px}.split-band-copy>a{background:#111;color:#fff;border-radius:12px}.split-band-examples{gap:18px}.dark-preview,.dark-preview-alt{transform:none}.dark-preview img{height:260px;border:0;border-radius:14px;box-shadow:none}.dark-preview span{color:#777}.dark-preview span b{color:#111}.more-sections{padding:78px 0 110px}.home-module-grid{gap:30px 18px}.module-title{color:#111}.module-tile-content p{color:#777}.mini-meta{color:#8B8B90}\n/* Library pages */\n.library-page{background:#fff}.library-masthead{display:grid;grid-template-columns:1fr minmax(320px,460px);align-items:end;gap:48px;padding:58px 0 30px;border-bottom:1px solid var(--line)}.library-masthead h1{font-size:clamp(44px,4.7vw,68px);letter-spacing:-3px;margin:7px 0 0}.library-masthead h1 span{display:none}.library-masthead>p{font-size:14px;color:#777;max-width:440px;line-height:1.65;margin:0 0 5px}.library-main--full{padding-top:24px}.library-tools{min-height:58px;border:1px solid #E3E3E6;border-radius:14px;box-shadow:none;background:#fff}.tool-search input{color:#111}.sort-label select{color:#111;background-image:none;padding-right:2px}.view-switch .on{background:#111;color:#fff}.filter-strip{display:flex;align-items:center;gap:8px;padding:14px 0 22px;overflow-x:auto;scrollbar-width:none;border-bottom:1px solid var(--line)}.filter-strip::-webkit-scrollbar{display:none}.filter-strip button{white-space:nowrap;border:1px solid #E2E2E5;background:#fff;color:#666;border-radius:999px;padding:9px 14px;font-size:12px;font-weight:650}.filter-strip button:hover{background:#F5F5F7;color:#111}.filter-strip button.active{background:#111;color:#fff;border-color:#111}.library-result-line{margin:20px 0 18px;color:#888}.library-result-line strong{color:#111}.library-result-line>span{color:#A0A0A5}.website-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:42px 22px}.module-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:42px 22px}.website-grid .site-image,.module-grid .module-picture{aspect-ratio:1.57}.no-results{border-color:#E5E5E7;background:#F7F7F8}.no-results button{background:#111}\n/* Detail / compare / board */\n.detail-media,.detail-side-block,.research-insight,.board-row,.pattern-card,.comparison-window,.quick-panel{background:#fff;border-color:#E5E5E7;box-shadow:none}.detail-actions .primary,.compare-tray-actions button.primary,.section-tabs button.active,.sidebar-choice.active{background:#111;color:#fff;border-color:#111}.section-tabs button{background:#fff;color:#666;border-color:#E2E2E5;border-radius:999px}.section-tabs button:hover{background:#F5F5F7;color:#111}.compare-tray{background:#111;color:#fff;box-shadow:0 16px 40px rgba(0,0,0,.14)}.compare-tray .overline{color:#AAA}.comparison-picture{background:#F5F5F7}.close-round{color:#111}.pattern-sample>div{background:#F5F5F7}.pattern-sample h2 .ic{color:#111}.secondary-page>p{color:#777}.site-footer{background:#fff;color:#666}.footer-row{border-color:#E5E5E7}\n/* Mobile / tablet */\n@media(max-width:1020px){.wrap{width:calc(100% - 48px)}.introduction{grid-template-columns:1fr;gap:22px;padding:42px 0 28px}.introduction h1{max-width:780px}.home-wall{grid-template-columns:repeat(2,minmax(0,1fr))}.home-wall>.site-tile--featured:first-child{grid-column:span 2}.library-masthead{grid-template-columns:1fr;gap:12px;padding:42px 0 26px}.library-masthead>p{max-width:620px}.split-band-inner{gap:44px}}\n@media(max-width:800px){.library-main--full{padding-top:18px}.filter-strip{padding-top:12px}.website-grid,.module-grid{grid-template-columns:1fr}.home-module-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.home-split-band{padding:54px 0}.split-band-inner{grid-template-columns:1fr}.dark-preview img{height:210px}}\n@media(max-width:600px){.wrap{width:calc(100% - 30px)}.introduction{padding:30px 0 22px}.introduction h1{font-size:40px;letter-spacing:-2px}.hero-note{font-size:12px}.intro-search{height:52px;border-radius:13px}.filters-quick{margin-bottom:26px;padding-bottom:18px}.home-wall{grid-template-columns:1fr;gap:28px}.home-wall>.site-tile--featured:first-child{grid-column:span 1}.home-gallery{padding-bottom:58px}.shelf-heading h2{font-size:24px}.site-image{border-radius:11px}.home-split-band{padding:44px 0}.split-band-examples{grid-template-columns:1fr 1fr}.dark-preview img{height:150px;border-radius:10px}.more-sections{padding:52px 0 72px}.library-masthead{padding:30px 0 20px}.library-masthead h1{font-size:44px;letter-spacing:-2.1px}.library-masthead>p{font-size:12px}.library-tools{min-height:52px;border-radius:12px}.filter-strip button{padding:8px 12px;font-size:10px}.website-grid,.module-grid{gap:30px}.home-module-grid{grid-template-columns:1fr}.site-tile-footer p{font-size:10px}.tile-name{font-size:14px}}\n'
if "V1.2 — refined monochrome system" not in css:
    css_path.write_text(css+"\n"+OVERRIDE)
print("Applied V1.2 monochrome layout patch")
